// ---- Mars Life Line style header (generated by scripts/kiln-style-sync.mjs from src/style/tokens.json, style v2) ----
// Paste at the top of every .kiln.js source. Do not edit colours here; edit tokens.json and re-run npm run style:sync.
const PALETTE = {
  'space-deep': 0x20283D,
  'shadow-plum': 0x765768,
  'regolith-mid': 0xB95C40,
  'regolith-light': 0xE6A26A,
  'structure-white': 0xF2E5D2,
  'structure-gray': 0x686976,
  'trim-dark': 0x303240,
  'accent-orange': 0xFF8A24,
  'accent-cyan': 0x54E5F5,
  'accent-blue': 0x35CFFF,
  'glass-tint': 0xEBD9C5,
  'cell-blue': 0x2F58B8
};

const BUDGETS = {"small-prop":1500,"medium-prop":6000,"vehicle":9000,"building":12000,"character":8000,"rock":400};
const SEGMENTS = {"small":8,"default":12,"large":16};

// Bevel radius for roundedBoxGeo: ratio of the smallest dimension (style range 0.06-0.12).
function bevel(w, h, d, ratio = 0.09) {
  return Math.min(w, h, d) * ratio;
}

// One shared material per role. Variants (e.g. structure-gray) take an explicit colour token.
function styleMaterials() {
  const m = {"matte-environment":{"description":"Terrain, rocks, craters, mountains. Fully matte, no reflections.","colors":["regolith-mid","regolith-light","shadow-plum"],"roughness":0.95,"metalness":0},"smooth-structure":{"description":"Buildings, modules, vehicles, suits, crates. Clean satin finish, never mirror-like.","colors":["structure-white","structure-gray"],"roughness":0.55,"metalness":0.05},"accent-paint":{"description":"Non-glowing orange colour blocking: side panels, crate faces, dome base band, suit pads, wheel hubs.","colors":["accent-orange"],"roughness":0.6,"metalness":0},"dark-trim":{"description":"Tyres, recesses, joints, vents.","colors":["trim-dark"],"roughness":0.85,"metalness":0},"emissive-warm":{"description":"Door frames, window strips, headlights. Selected surfaces only.","colors":["accent-orange"],"emissive":"accent-orange","emissiveIntensity":1.6,"roughness":0.5,"metalness":0},"emissive-cool":{"description":"Beacons, indicators, screens. Smaller and rarer than warm lights.","colors":["accent-cyan","accent-blue"],"emissive":"accent-cyan","emissiveIntensity":1.4,"roughness":0.5,"metalness":0},"glass":{"description":"Greenhouse domes, module windows. Light tint, soft highlight, see-through.","colors":["glass-tint"],"roughness":0.15,"metalness":0,"opacity":0.35},"visor":{"description":"Helmet visors and vehicle windshields. Opaque near-black, glossy, shows a soft highlight.","colors":["space-deep"],"roughness":0.12,"metalness":0.1},"solar-cell":{"description":"Solar panel cell faces. Deep blue, semi-gloss, framed by structure-white grid bars.","colors":["cell-blue"],"roughness":0.35,"metalness":0.1}};
  const make = (role, colorToken) => {
    const spec = m[role];
    const color = PALETTE[colorToken ?? spec.colors[0]];
    const name = colorToken && colorToken !== spec.colors[0] ? role + ':' + colorToken : role;
    if (role === 'glass') return glassMaterial(color, { opacity: spec.opacity, roughness: spec.roughness, metalness: spec.metalness, name });
    const opts = { roughness: spec.roughness, metalness: spec.metalness, name };
    if (spec.emissive) Object.assign(opts, { emissive: PALETTE[spec.emissive], emissiveIntensity: spec.emissiveIntensity });
    return gameMaterial(color, opts);
  };
  return {
    rock: make('matte-environment'),
    rockLight: make('matte-environment', 'regolith-light'),
    rockShadow: make('matte-environment', 'shadow-plum'),
    panel: make('smooth-structure'),
    panelGray: make('smooth-structure', 'structure-gray'),
    accent: make('accent-paint'),
    trim: make('dark-trim'),
    glowWarm: make('emissive-warm'),
    glowCool: make('emissive-cool'),
    glowBlue: make('emissive-cool', 'accent-blue'),
    glass: make('glass'),
    visor: make('visor'),
    solarCell: make('solar-cell'),
  };
}
// ---- end style header ----

const meta = {
  name: 'flag-plaque',
  role: 'prop',
  reference: 'models and assets images/phase-4/flag-plaque.png'
};

function build() {
  const root = createRoot('flag-plaque');
  const m = styleMaterials();

  // -------------------------------------------------------------------------
  // 1. WALL BRACKETS (Mounts at left side in front view: Z = +0.36)
  // -------------------------------------------------------------------------
  for (const y of [0.42, 0.18]) {
    const id = y > 0.3 ? 'Top' : 'Bottom';
    // Wall mounting flange plate
    createPart('WallFlange_' + id, boxGeo(0.08, 0.16, 0.035), m.panelGray, {
      position: [0, y, 0.37],
      parent: root
    });
    // Bolt indentations
    for (const b of [-0.05, 0.05]) {
      createPart('Bolt_' + id + (b > 0 ? '_Up' : '_Dn'), cylinderGeo(0.012, 0.012, 0.01, 8), m.trim, {
        position: [0, y + b, 0.35],
        rotation: [90, 0, 0],
        parent: root
      });
    }
    // Cantilever bracket arm
    createPart('BracketArm_' + id, boxGeo(0.065, 0.065, 0.14), m.panelGray, {
      position: [0, y, 0.28],
      parent: root
    });
  }

  // -------------------------------------------------------------------------
  // 2. MAIN SIGN OCTAGONAL FRAME
  // Plaque centered at Z = -0.22, Y = 0.30
  // Size: depth X = 0.10, height Y = 0.50, width Z = 0.86
  // -------------------------------------------------------------------------
  const plaque = createPivot('Plaque', [0, 0.30, -0.22], root);

  // Outer slate border frame (octagonal chamfered shape)
  createPart('FrameMain', boxGeo(0.10, 0.38, 0.86), m.panelGray, {
    position: [0, 0, 0],
    parent: plaque
  });
  createPart('FrameCross', boxGeo(0.10, 0.50, 0.72), m.panelGray, {
    position: [0, 0, 0],
    parent: plaque
  });
  // Smooth chamfer corner plates
  for (const [cy, cz, rot] of [
    [0.19, 0.36, 45],
    [0.19, -0.36, -45],
    [-0.19, 0.36, -45],
    [-0.19, -0.36, 45]
  ]) {
    createPart(`FrameCorner_${cy > 0 ? 'T' : 'B'}_${cz > 0 ? 'R' : 'L'}`, boxGeo(0.099, 0.02, 0.16), m.panelGray, {
      position: [0, cy, cz],
      rotation: [rot, 0, 0],
      parent: plaque
    });
  }

  // Recessed Ivory Face Plate (front +X)
  createPart('FaceMainFront', boxGeo(0.025, 0.32, 0.80), m.panel, {
    position: [0.045, 0, 0],
    parent: plaque
  });
  createPart('FaceCrossFront', boxGeo(0.025, 0.44, 0.68), m.panel, {
    position: [0.045, 0, 0],
    parent: plaque
  });

  // Four Orange Chamfer Tabs on Front (+X)
  const tabPositionsFront = [
    [-0.17, 0.32, -45], // Bottom-Right
    [0.17, 0.32, 45],  // Top-Right
    [-0.17, -0.32, 45], // Bottom-Left
    [0.17, -0.32, -45]   // Top-Left
  ];
  tabPositionsFront.forEach(([ty, tz, rot], i) => {
    createPart('OrangeTabFront_' + i, boxGeo(0.035, 0.02, 0.12), m.accent, {
      position: [0.05, ty, tz],
      rotation: [rot, 0, 0],
      parent: plaque
    });
  });

  // -------------------------------------------------------------------------
  // 3. RAISED BLOCK LETTERING: "LIFE LINE" / "STATION"
  // -------------------------------------------------------------------------
  const textGroup = createPivot('TextFront', [0.065, 0, 0], plaque);

  let strokeIdx = 0;
  function addStroke(w, h, py, pz) {
    createPart('Strk_' + (strokeIdx++), boxGeo(0.015, h, w), m.panelGray, {
      position: [0, py, pz],
      parent: textGroup
    });
  }

  function letterL(py, pz) {
    addStroke(0.014, 0.10, py, pz + 0.018); // left vert (+Z)
    addStroke(0.046, 0.014, py - 0.043, pz); // bottom bar
  }
  function letterI(py, pz) {
    addStroke(0.014, 0.10, py, pz);
  }
  function letterF(py, pz) {
    addStroke(0.014, 0.10, py, pz + 0.018); // left vert (+Z)
    addStroke(0.044, 0.014, py + 0.043, pz); // top bar
    addStroke(0.036, 0.014, py + 0.005, pz + 0.004); // mid bar
  }
  function letterE(py, pz) {
    addStroke(0.014, 0.10, py, pz + 0.018); // left vert (+Z)
    addStroke(0.046, 0.014, py + 0.043, pz); // top bar
    addStroke(0.036, 0.014, py + 0.005, pz + 0.004); // mid bar
    addStroke(0.046, 0.014, py - 0.043, pz); // base bar
  }
  function letterN(py, pz) {
    addStroke(0.014, 0.10, py, pz + 0.018); // left vert (+Z)
    addStroke(0.014, 0.10, py, pz - 0.018); // right vert (-Z)
    createPart('Strk_' + (strokeIdx++), boxGeo(0.015, 0.105, 0.014), m.panelGray, {
      position: [0, py, pz],
      rotation: [36, 0, 0],
      parent: textGroup
    });
  }
  function letterS(py, pz) {
    addStroke(0.046, 0.014, py + 0.043, pz); // top
    addStroke(0.014, 0.040, py + 0.023, pz + 0.016); // upper left (+Z)
    addStroke(0.046, 0.014, py, pz); // mid
    addStroke(0.014, 0.040, py - 0.023, pz - 0.016); // lower right (-Z)
    addStroke(0.046, 0.014, py - 0.043, pz); // bot
  }
  function letterT(py, pz) {
    addStroke(0.048, 0.014, py + 0.043, pz); // top
    addStroke(0.014, 0.09, py - 0.005, pz); // vert
  }
  function letterA(py, pz) {
    addStroke(0.014, 0.10, py, pz + 0.018); // left vert (+Z)
    addStroke(0.014, 0.10, py, pz - 0.018); // right vert (-Z)
    addStroke(0.046, 0.014, py + 0.043, pz); // top
    addStroke(0.036, 0.014, py, pz); // crossbar
  }
  function letterO(py, pz) {
    addStroke(0.014, 0.10, py, pz + 0.018); // left vert
    addStroke(0.014, 0.10, py, pz - 0.018); // right vert
    addStroke(0.046, 0.014, py + 0.043, pz); // top
    addStroke(0.046, 0.014, py - 0.043, pz); // bot
  }

  // Row 1: "LIFE LINE" from +Z down to -Z at Y = +0.08
  const yRow1 = 0.08;
  letterL(yRow1, 0.28);
  letterI(yRow1, 0.22);
  letterF(yRow1, 0.16);
  letterE(yRow1, 0.09);

  letterL(yRow1, -0.08);
  letterI(yRow1, -0.14);
  letterN(yRow1, -0.20);
  letterE(yRow1, -0.27);

  // Row 2: "STATION" from +Z down to -Z at Y = -0.08
  const yRow2 = -0.08;
  letterS(yRow2, 0.25);
  letterT(yRow2, 0.17);
  letterA(yRow2, 0.09);
  letterT(yRow2, 0.01);
  letterI(yRow2, -0.07);
  letterO(yRow2, -0.15);
  letterN(yRow2, -0.24);

  defineBudget({ triangles: BUDGETS['small-prop'] }, root);
  return root;
}
